insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0001','概念データモデル','概念データモデルの説明として、最も適切なものはどれか。','DM-A-17-02-01','ipa_past','出典：令和7年度 秋期 データベーススペシャリスト試験 午前Ⅱ 問2','[{"id": 1, "body": "階層モデル、ネットワークモデル、関係モデルがある。"}, {"id": 2, "body": "業務プロセスを抽象化して表現したものである。"}, {"id": 3, "body": "集中型DBMSを導入するか、分散型DBMSを導入するかによって内容が変わる。"}, {"id": 4, "body": "対象世界の情報構造を抽象化して表現したものである。"}]'::jsonb,4,'概念データモデルは対象となる業務世界の情報構造を抽象化して表す。業務手順を表すものでも、特定DBMSの配置方式に依存するものでもない。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0002','UMLの多重度','UMLを用いて表した商品と倉庫のデータモデルに関する記述のうち、適切なものはどれか。ここで、商品の倉庫間の移動はないものとする。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0003','モデルと具体例の整合性','データモデルを解釈してオブジェクト図を作成した。解釈の誤りを適切に指摘した記述はどれか。ここで、モデルの表記にはUMLを用い、オブジェクト図の一部の属性の表示は省略した。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0004','学習と推論','クラウドで学習し、エッジデバイスで推論する機械学習ベースのエッジAIにおいて、エッジデバイスで行われる推論処理として、適切なものはどれか。','DM-A-10-02-03','ipa_past','出典：令和7年度 春期 高度試験共通 午前Ⅰ 問27／出典：令和7年度 春期 応用情報技術者試験 午前 問71','[{"id": 1, "body": "一定の環境の中で試行錯誤を行い、行動に報酬を与えることで学習するプロセス"}, {"id": 2, "body": "学習したモデルに従い、実際にデータの識別などを行うプロセス"}, {"id": 3, "body": "識別などを行うためのモデルを、正解のラベルを付けたデータによって作成するプロセス"}, {"id": 4, "body": "識別などを行うためのモデルを、正解のラベルを付けないデータによって作成するプロセス"}]'::jsonb,2,'推論は学習済みのモデルを用いて新しい入力に対する識別や予測を行う処理である。ほかの選択肢は学習の方法を説明している。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0005','画像認識AIの活用','スマートファクトリーで使用されるAIを用いたマシンビジョンの目的として、適切なものはどれか。','DM-A-10-02-02','ipa_past','出典：令和7年度 春期 高度試験共通 午前Ⅰ 問28／出典：令和7年度 春期 応用情報技術者試験 午前 問72','[{"id": 1, "body": "クラウドに蓄積した入出荷データを用いてAIが需要を予測し、生産数を最適化する。"}, {"id": 2, "body": "作業者が装着したVRゴーグルにAIが作業状況に応じたガイドを表示することによって、作業効率を向上させる。"}, {"id": 3, "body": "設計変更内容をAIによって整理し、製造現場に正確に伝える。"}, {"id": 4, "body": "人間の目視検査をAIが代替し、検査効率を向上させる。"}]'::jsonb,4,'マシンビジョンは画像から対象の状態などを認識する用途で使われる。選択肢では、製品の外観などを対象にした目視検査の代替が対応する。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0006','生成AIと著作権','著作権法及び関連法令によれば、生成AIを利用して画像を生成する行為又はその生成物の利用が著作権侵害にあたるか否かに関して、適切な記述はどれか。','DM-A-28-01-05','ipa_past','出典：令和7年度 春期 高度試験共通 午前Ⅰ 問30／出典：令和7年度 春期 応用情報技術者試験 午前 問78','[{"id": 1, "body": "AIが既存の著作権で保護されている画像をデータセットとして学習している場合は、そのAIを利用して画像を生成すると、いかなる場合も著作権侵害になる。"}, {"id": 2, "body": "AIを利用して生成した画像が著作権で保護された既存の画像と類似しており、それを公開した場合、著作権侵害となる可能性がある。"}, {"id": 3, "body": "AIを利用して生成した画像は、AIが自動的に創作したものであるため、いかなる状況でも著作権の対象外となり、著作権侵害の懸念は生じない。"}, {"id": 4, "body": "AIを利用して生成した画像は、生成した本人の私的使用に限って、利用が認められており、商業利用を行った場合は、いかなる場合も著作権侵害となる。"}]'::jsonb,2,'公式正答はイ。既存著作物との関係によって生成物の公開が侵害となる可能性はある。ほかの選択肢の「いかなる場合も」「いかなる状況でも」という一律の説明は適切ではない。個別の権利判断や現在の法令解釈を保証する解説ではなく、原試験の選択肢を理解するための説明。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0007','セキュリティの基本特性','JIS Q 27000:2019（情報セキュリティマネジメントシステム－用語）における真正性及び信頼性に対する定義a～dの組合せのうち、適切なものはどれか。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0008','製造時間の制約と利益','表のような製品A、Bを製造、販売する場合、考えられる利益は最大で何円になるか。ここで、機械の年間使用可能時間は延べ15,000時間とし、年間の固定費は製品A、Bに関係なく15,000,000円とする。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0009','リスク対応','JIS Q 27000:2019（情報セキュリティマネジメントシステム－用語）におけるリスク対応についての説明として、適切なものはどれか。','DM-A-24-03-02','ipa_past','出典：令和7年度 秋期 システム監査技術者試験 午前Ⅱ 問19','[{"id": 1, "body": "リスク及びその大きさが受容可能か否かを決定するために、リスク分析の結果をリスク基準と比較するプロセス"}, {"id": 2, "body": "リスクの特質を理解し、リスクレベルを決定するプロセス"}, {"id": 3, "body": "リスクの発見、認識及び記述を行うプロセス"}, {"id": 4, "body": "リスクを修正するプロセス"}]'::jsonb,4,'リスク対応はリスクを修正するプロセスに対応する。アはリスク評価、イはリスク分析、ウはリスク特定の説明。規格由来の表現は公開前の権利確認対象とする。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0010','需要予測と時系列','様々な需要予測モデルのもととなっている時系列モデルに関する記述のうち、適切なものはどれか。','DM-A-09-03-04','ipa_past','出典：令和7年度 春期 応用情報技術者試験 午前 問74','[{"id": 1, "body": "移動平均法では、平均する期間を長くするほど、短期的な需要の変化の影響を大きく受ける。"}, {"id": 2, "body": "移動平均法は、長期的な需要のトレンドを把握するのには向かないが、直近の需要の変化を把握するのに向いている。"}, {"id": 3, "body": "指数平滑法では、平滑化定数の値が0%に近いほど直前の実績値を重視し、100%に近いほど過去の実績値を重視する。"}, {"id": 4, "body": "指数平滑法は、過去の実績値よりも直近の実績値を用いるほど予測の精度が向上すると考えられる場合に有効な手法である。"}]'::jsonb,4,'単純指数平滑法では平滑化定数が大きいほど直近の実績を強く反映する。移動平均の期間を長くすると短期変動は平滑化される。原問の選択肢ではエが適切。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0011','購買データの関連性','データ分析手法の一つである、アソシエーション分析はどれか。','DM-A-09-02-10','ipa_past','出典：令和7年度 秋期 応用情報技術者試験 午前 問63','[{"id": 1, "body": "結果となる数値（目的変数）と要因となる数値（説明変数）との関係性について、最小二乗法を用いて分析する。気温の変化が売行きにどの程度影響するかなどの事象の予測に用いることができる。"}, {"id": 2, "body": "商品を購買するときの関連性や同時性などのルールを購買データによって見いだす。データ間の統計的なパターンや、意味のある関連性を抽出する。信頼度、支持度及びリフト値によってルールを評価し、有効性を確認する。"}, {"id": 3, "body": "多数の変数の情報（観測変数）に存する共通因子を仮定して、モデル化して分析する。共通因子を見つけることによってデータの数が増加しても複雑になることを防ぎ、現象を分かりやすく捉えることができる。"}, {"id": 4, "body": "多数の変数の情報（観測変数）をできるだけ少ない指標や次元（合成変数）で要約する。データのもつ情報をできる限り損なわずに全体の傾向を可視化することができる。"}]'::jsonb,2,'アソシエーション分析では一緒に購入される商品などの関連ルールを見つける。支持度・信頼度・リフト値を用いる説明が対応する。アは回帰、ウは因子分析、エは主成分分析の説明。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0012','部品制約と利益最大化','製品X、Yを1台製造するのに必要な部品数は、表のとおりである。製品X、Yの1台当たりの利益が、それぞれ1万円のとき、利益は最大何万円になるか。ここで、部品Aは120個、部品Bは60個まで使えるものとする。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0013','著作権の保護対象','著作権法において、保護の対象とならないものはどれか。','DM-A-28-01-03','ipa_past','出典：令和7年度 秋期 応用情報技術者試験 午前 問78','[{"id": 1, "body": "インターネットで公開されたフリーソフトウェア"}, {"id": 2, "body": "ソフトウェアの操作マニュアル"}, {"id": 3, "body": "データベース"}, {"id": 4, "body": "プログラム言語や規約（プログラム言語の用法についての特別の約束）"}]'::jsonb,4,'原試験の正答はエ。プログラム言語や規約は著作権法の当該保護対象から除かれる。無料公開というだけで著作権がなくなるわけではない。また、データベースは情報の選択や体系的構成に創作性があれば保護され得る。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0014','顧客コードの定義管理','二つの部署で「有効顧客」の定義が異なり、全社集計が一致しない。データガバナンスの観点で最も適切な対応はどれか。','DM-A-08-03-01','ai_original','AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。','[{"id": 1, "body": "集計担当者が毎月都合のよい定義を選び、記録せず集計する。"}, {"id": 2, "body": "全社で合意する定義と責任者、変更手順を定め、各部署へ周知する。"}, {"id": 3, "body": "値が一致するまで元データを削除する。"}, {"id": 4, "body": "定義を共有せず、集計ツールだけを統一する。"}]'::jsonb,2,'定義と責任・変更手順の合意を組織として管理することが重要。場当たり的な定義変更、データ削除、ツールのみの統一では原因を解消できない。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0015','欠損値の取扱い','アンケートの年齢欄に未回答がある。平均年齢を集計する前のデータ品質管理として、最も適切な対応はどれか。','DM-A-08-04-02','ai_original','AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。','[{"id": 1, "body": "未回答を全て0歳に置き換え、置換したことは記録しない。"}, {"id": 2, "body": "未回答者の年齢を担当者の推測で埋める。"}, {"id": 3, "body": "欠損の発生状況を確認し、分析目的に沿った除外・補完の方針と処理内容を記録する。"}, {"id": 4, "body": "回答済みの値も全て平均値に置き換える。"}]'::jsonb,3,'欠損の扱いは分析目的と発生状況によって判断する必要がある。0や推測による無記録の補完は集計を歪める。回答済みの値を消すことも適切ではない。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0016','ビジネスメタデータ','売上データのデータカタログに登録する情報のうち、ビジネスメタデータとして最も適切なものはどれか。','DM-A-08-05-01','ai_original','AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。','[{"id": 1, "body": "売上金額は返品を控除した税抜金額である、という業務上の定義"}, {"id": 2, "body": "データベース製品のパッチ番号"}, {"id": 3, "body": "列を格納する物理ファイルのパス"}, {"id": 4, "body": "前回のバックアップジョブの実行時間"}]'::jsonb,1,'ビジネスメタデータはデータの業務上の意味や定義を表す。ほかの選択肢は技術情報や運用情報であり、売上金額の業務上の意味を説明していない。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0017','生成AIの回答の確認','社内資料を調べるために生成AIを利用したところ、もっともらしい説明と参考資料名が出力された。情報倫理・AI倫理の観点で最も適切な対応はどれか。','DM-A-27-02-01','ai_original','AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。','[{"id": 1, "body": "資料名が記載されているため、内容を確認せず社外へ公開する。"}, {"id": 2, "body": "文章が自然であることを正しさの根拠にする。"}, {"id": 3, "body": "別の生成AIが同意すれば、元資料の確認は不要とする。"}, {"id": 4, "body": "元資料の実在と該当箇所を確認し、出力内容の正確性を検証する。"}]'::jsonb,4,'生成AIは誤った内容や実在しない出典を出すことがある。元資料の確認が必要で、文章の自然さや別AIの同意だけでは根拠を確認したことにならない。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0018','利用目的と同意の記録','顧客が任意の販促メール配信を受けることに事前に同意した場合だけ配信する社内ルールを設けた。この方式と同意情報の管理として最も適切なものはどれか。','DM-A-29-01-01','ai_original','AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。','[{"id": 1, "body": "オプトアウト方式であり、同意を得た記録は不要である。"}, {"id": 2, "body": "オプトイン方式であり、同意の有無と対象となる配信目的を確認できるよう記録する。"}, {"id": 3, "body": "オプトイン方式であり、一度同意すれば配信目的を無制限に変更できる。"}, {"id": 4, "body": "匿名加工の方式であり、メールアドレスは個人に結び付かなくなる。"}]'::jsonb,2,'事前の同意に基づく方式はオプトイン。何に同意したかを確認できるよう管理する。問題文の社内ルールに基づく概念問題であり、個別の法令上の同意要件を断定するものではない。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0019','ディープラーニングの特徴','AIにおけるディープラーニングに関する記述として、最も適切なものはどれか。','DM-A-10-02-03','ipa_past','出典：令和6年度 春期 応用情報技術者試験 午前 問3（句読点を統一。解説は独自作成）','[{"id": 1, "body": "あるデータから結果を求める処理を、人間の脳神経回路のように多層の処理を重ねることによって、複雑な判断をできるようにする。"}, {"id": 2, "body": "大量のデータからまだ知られていない新たな規則や仮説を発見するために、想定値から大きく外れている例外事項を取り除きながら分析を繰り返す手法である。"}, {"id": 3, "body": "多様なデータや大量のデータに対して、三段論法、統計的手法やパターン認識手法を組み合わせることによって、高度なデータ分析を行う手法である。"}, {"id": 4, "body": "知識がルールに従って表現されており、演繹手法を利用した推論によって有意な結論を導く手法である。"}]'::jsonb,1,'ディープラーニングは、多層のニューラルネットワークによってデータの特徴を学習する手法である。単に大量のデータを使うことや、ルールに基づく推論と同じ意味ではない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0020','連関図による原因の整理','分析対象としている問題に数多くの要因が関係し、それらが相互に絡み合っているとき、原因と結果、目的と手段といった関係を追求していくことによって、因果関係を明らかにし、解決の糸口をつかむための図はどれか。','DM-A-09-03-03','ipa_past','出典：令和6年度 春期 応用情報技術者試験 午前 問74（句読点を統一。解説は独自作成）','[{"id": 1, "body": "アローダイアグラム"}, {"id": 2, "body": "パレート図"}, {"id": 3, "body": "マトリックス図"}, {"id": 4, "body": "連関図"}]'::jsonb,4,'連関図は、問題に関係する要因を因果関係で結び、複雑に絡む関係を整理する。パレート図は件数などの大きい項目を把握し、マトリックス図は二つ以上の要素の対応関係を整理するために用いる。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0021','要配慮個人情報','個人情報のうち、個人情報保護法における要配慮個人情報に該当するものはどれか。','DM-A-29-01-01','ipa_past','出典：令和6年度 春期 応用情報技術者試験 午前 問80（句読点を統一。解説は独自作成）','[{"id": 1, "body": "個人情報の取得時に、本人が取扱いの配慮を申告することによって設定される情報"}, {"id": 2, "body": "個人に割り当てられた、運転免許証、クレジットカードなどの番号"}, {"id": 3, "body": "生存する個人に関する、個人を特定するために用いられる勤務先や住所などの情報"}, {"id": 4, "body": "本人の病歴、犯罪の経歴など不当な差別や不利益を生じさせるおそれのある情報"}]'::jsonb,4,'要配慮個人情報には、病歴や犯罪の経歴など、取扱いに特に配慮を要する情報が含まれる。本人が配慮を申し出た情報すべてを意味するのではない。番号や住所は個人情報になり得るが、それだけで要配慮個人情報に該当するとは限らない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0022','交差検証による汎化性能の評価','AIにおける教師あり学習での交差検証に関する記述はどれか。','DM-A-10-02-03','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問2（句読点を統一。解説は独自作成）','[{"id": 1, "body": "過学習を防ぐために、回帰モデルに複雑さを表すペナルティ項を加え、訓練データへ過剰に適合しないようにモデルを調整する。"}, {"id": 2, "body": "学習の精度を高めるために、複数の異なるアルゴリズムのモデルで学習し、学習の結果は組み合わせて評価する。"}, {"id": 3, "body": "学習モデルの汎化性能を高めるために、単一のモデルで関連する複数の課題を学習することによって、課題間に共通する要因を獲得する。"}, {"id": 4, "body": "学習モデルの汎化性能を評価するために、データを複数のグループに分割し、一部を学習に残りを評価に使い、順にグループを入れ替えて学習と評価を繰り返す。"}]'::jsonb,4,'交差検証は、データを分割し、学習用と評価用を入れ替えて性能を評価する方法である。未知のデータへの対応力である汎化性能を見積もる。ほかの選択肢は順に正則化、アンサンブル学習、マルチタスク学習の説明である。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0023','オープンデータ・バイ・デザイン','官民データ活用推進基本法などに基づいて進められているオープンデータバイデザインに関して、行政機関における取組についての記述として、適切なものはどれか。','DM-A-09-02-01','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問62（句読点を統一。解説は独自作成）','[{"id": 1, "body": "行政機関が保有する個人情報を産業振興などの目的でオープン化する場合は、データ公開に先立ち、個人情報保護委員会への届出が義務化されている。"}, {"id": 2, "body": "行政機関において収集・蓄積された既存のデータが公開される場合、営利目的の利用は許されておらず、非営利の用途に限って利用が認められている。"}, {"id": 3, "body": "行政機関における情報システムの設計において、情報セキュリティを確保する観点から、公開するデータの用途を行政機関同士の相互利用に限定している。"}, {"id": 4, "body": "対象となる行政データを、二次利用や機械判読に適した形態で無償公開することを前提に、情報システムや業務プロセスの企画、整備及び運用を行っている。"}]'::jsonb,4,'オープンデータ・バイ・デザインでは、データ公開を後から付け足すのではなく、企画や設計の段階から二次利用や機械判読を考慮する。オープンデータは営利利用や行政機関以外の利用を一律に排除するものではなく、個人情報を無条件に公開する考え方でもない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0024','ECRSによる業務改善','業務改善の4原則としてのEliminate、Combine、Rearrange、Simplifyは、業務改善を実現する上での視点を示すものである。次の業務改善例のうち、Rearrangeを適用したものはどれか。','DM-A-09-03-03','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問63（句読点を統一。解説は独自作成）','[{"id": 1, "body": "経費精算申請業務において、決裁に不要な人を申請フローから外し、決裁までに要する時間を短縮した。"}, {"id": 2, "body": "商品配送ルートを可視化した結果、移動距離の無駄が発見された。そこで、配送順を入れ替えることで、一日に配送できる件数を向上させた。"}, {"id": 3, "body": "表計算ソフト上で各項目を手入力していたが、一つの項目を入力すれば他の関連項目が自動計算できるように関数を設定し、作業効率を向上させた。"}, {"id": 4, "body": "複数部門が集まる会議の議事録を、各部門のスタッフが、それぞれ独自に作成していた。各部門での作成をやめ、代表者1名が作成し、部門間で共有した。"}]'::jsonb,2,'Rearrangeは、作業の順序や配置を入れ替えて改善する視点である。配送順の変更が該当する。ほかの選択肢は順にEliminate（排除）、Simplify（簡素化）、Combine（結合）に対応する。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0025','ファインチューニング','生成AIのビジネス活用において、独自のデータを学習させることにより基盤モデルを自社の業務やサービスに特化したモデルへとカスタマイズすることを何と呼ぶか。','DM-A-10-03-02','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問71（句読点を統一。解説は独自作成）','[{"id": 1, "body": "アノテーション"}, {"id": 2, "body": "クラスタリング"}, {"id": 3, "body": "ファインチューニング"}, {"id": 4, "body": "プロンプトエンジニアリング"}]'::jsonb,3,'ファインチューニングは、学習済みのモデルに追加のデータで学習を行い、用途に適合させる方法である。プロンプトエンジニアリングは入力する指示を工夫する方法であり、モデルの追加学習とは区別する。アノテーションはデータへのラベル付け、クラスタリングは類似するデータのグループ化を指す。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0026','ベイズ統計の考え方','ベイズ統計の説明として、適切なものはどれか。','DM-A-09-02-03','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問76（句読点を統一。解説は独自作成）','[{"id": 1, "body": "経済統計に関する国際条約に基づいて、貿易実態を正確に把握し、国の経済政策や企業の経済活動の資料とすることを目的とした指標を作成する統計手法"}, {"id": 2, "body": "事前分布・事後分布といった確率に関する考え方に基づいて体系化されたものであり、機械学習、迷惑メールフィルターなどに利用されている統計理論"}, {"id": 3, "body": "収集されたデータの代表値である平均値・中央値・最頻値を求めたり、度数分布表やヒストグラムを作成したりすることによって、データの特徴を捉える統計理論"}, {"id": 4, "body": "ビッグデータの収集・分析に当たり、分析結果の検証可能性を確保し、複数の分析結果を比較可能とするために、対象をオープンデータに限定する統計手法"}]'::jsonb,2,'ベイズ統計では、事前の確率に新たな観測結果を反映し、事後の確率へ更新する。迷惑メール判定などにも利用される。代表値やヒストグラムによってデータの特徴を要約する説明は記述統計に対応する。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0027','プログラムと著作権','著作権法で保護されるものはどれか。','DM-A-28-01-03','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問78（句読点を統一。解説は独自作成）','[{"id": 1, "body": "アルゴリズム"}, {"id": 2, "body": "コンパイラのプログラム"}, {"id": 3, "body": "プログラム言語"}, {"id": 4, "body": "プロトコル"}]'::jsonb,2,'プログラムは、創作性のある具体的な表現として著作物になり得る。アルゴリズムという解法そのもの、プログラム言語、規約であるプロトコルとは区別する。原試験ではコンパイラのプログラムが正答である。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0028','フィルターバブル','SNSやWeb検索などに関して、イーライ・パリサーが提唱したフィルターバブルの記述として、適切なものはどれか。','DM-A-27-01-02','ipa_past','出典：令和6年度 春期 ITストラテジスト試験 午前Ⅱ 問17（句読点を統一。解説は独自作成）','[{"id": 1, "body": "PCやスマートフォンなど、使用する機器の性能やソフトウェアの機能に応じて、利用者は情報へのアクセスにフィルターがかかっており、様々な格差が生じている。"}, {"id": 2, "body": "SNS、Webの一般のインターネット利用者が発信する情報が増えたことによって、Web検索の結果は非常に膨大なものとなり、個人による適切な情報収集が難しくなった。"}, {"id": 3, "body": "広告収入を目的に、事実とは異なるフィルターのかかったニュースがSNSなどを通じて発信されるようになったので、正確な情報を検索することが困難になった。"}, {"id": 4, "body": "利用者の属性・行動などに応じ、好ましいと考えられる情報がより多く表示され、利用者は実社会とは隔てられたパーソナライズされた情報空間へと包まれる。"}]'::jsonb,4,'フィルターバブルは、個人に合わせた情報の選別によって、接する情報が偏り、異なる見方に触れにくくなる現象である。機器による情報格差、情報量の増大、偽情報の発信それ自体とは区別する。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0029','親和図による情報の整理','親和図の特徴はどれか。','DM-A-09-03-05','ipa_past','出典：令和6年度 春期 ITストラテジスト試験 午前Ⅱ 問19（句読点を統一。解説は独自作成）','[{"id": 1, "body": "原因と結果を対比させた図式表現であり、不良原因の追及に用いられる。"}, {"id": 2, "body": "錯綜した問題点や、まとまっていない意見、アイディアなどを整理し、まとめるために用いられる。"}, {"id": 3, "body": "二つ以上の変数の相互関係を表すのに役立つ。"}, {"id": 4, "body": "分布の形、目標値からのばらつき状態などから、製品の品質の状態が規格値に対して満足しているものかなどを判断するために用いられる。"}]'::jsonb,2,'親和図は、集めた意見や情報を内容の近さによってグループ化して整理する。ほかの選択肢は順に特性要因図、マトリックス図、ヒストグラムの用途に対応する。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0030','AI学習と非享受目的の著作物利用','公衆への提供などが行われた他人の著作物をAIの学習データとして利用する行為に関して、著作権法に照らして適切なものはどれか。ただし、著作物の利用は、AIによる情報解析の範囲で行われ、著作物に表現された思想又は感情を享受することを目的とするものではない。また、日本国内で作成された著作物を日本国内で利用する場合であり、利用者と著作権者との間で特段の契約は存在しないものとする。','DM-A-28-01-05','ipa_past','出典：令和6年度 春期 ITストラテジスト試験 午前Ⅱ 問22（句読点を統一。解説は独自作成）','[{"id": 1, "body": "他人の著作物から情報を抽出してAIに学習させる行為は、どのような条件においても、一切禁止されている。"}, {"id": 2, "body": "著作権者の許諾が得られた場合に限って、著作権者との合意の範囲内において、AIの学習に利用できる。"}, {"id": 3, "body": "著作権者の利益を不当に害さない場合、その必要と認められる限度において、商業利用であるか否かを問わず、著作権者の許諾なくAIの学習に利用できる。"}, {"id": 4, "body": "著作権者の利益を不当に害する場合及び商業利用の場合を除いて、著作権者の許諾なくAIの学習に利用できる。"}]'::jsonb,3,'問題文の非享受目的などの前提では、著作権法第30条の4により、必要と認められる限度で利用できる場合がある。商業利用であることだけで一律に除外されるわけではない。著作権者の利益を不当に害する場合は対象外であり、AI学習全般が無条件に自由という意味ではない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0031','職務著作と公表名義','著作権法及び関連法令によれば、職務著作の要件のうち、プログラムの著作物の場合は満たす必要がなく、プログラム以外の著作物の場合は満たす必要があるものはどれか。','DM-A-28-01-03','ipa_past','出典：令和6年度 秋期 システム監査技術者試験 午前Ⅱ 問13（句読点を統一。解説は独自作成）','[{"id": 1, "body": "著作権が作成者に帰属するとの取決めがないこと"}, {"id": 2, "body": "法人等が自己の著作の名義の下に公表していること"}, {"id": 3, "body": "法人等の業務に従事する者が作成していること"}, {"id": 4, "body": "法人等の発意に基づいていること"}]'::jsonb,2,'職務著作では法人等の発意や職務上の作成などの要件が問題になる。プログラムの著作物については、法人等の名義で公表するという要件は課されない。プログラム以外の著作物との違いを問う問題であり、単に会社で作ったものすべてが自動的に職務著作になるという意味ではない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0032','エラープルーフによるミスの予防','ヒューマンエラーに起因する障害の低減策の一つに、エラープルーフ化がある。エラープルーフ化の五つの原理のうち、作業ミスによるエラーの発生を未然に防ぐための原理の組みはどれか。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0033','ベイジアンフィルター','迷惑メールの検知手法であるベイジアンフィルターの説明はどれか。','DM-A-10-02-03','ipa_past','出典：令和6年度 秋期 データベーススペシャリスト試験 午前Ⅱ 問20（句読点を統一。解説は独自作成）','[{"id": 1, "body": "信頼できるメール送信元を許可リストに登録しておき、許可リストにないメール送信元からの電子メールは迷惑メールと判定する。"}, {"id": 2, "body": "電子メールが正規のメールサーバから送信されていることを検証し、迷惑メールであるかどうかを判定する。"}, {"id": 3, "body": "電子メールの第三者中継を許可しているメールサーバを登録したデータベースの掲載情報を基に、迷惑メールであるかどうかを判定する。"}, {"id": 4, "body": "利用者が振り分けた迷惑メールと正規のメールから特徴を学習し、迷惑メールであるかどうかを統計的に判定する。"}]'::jsonb,4,'ベイジアンフィルターは、分類済みのメールに含まれる語句などの特徴を学習し、迷惑メールである確率を用いて判定する。送信元の許可リストや、送信元サーバの正当性の確認だけで分類する手法ではない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0034','リスク特定で考慮する資産の価値','JIS Q 31000:2019（リスクマネジメント－指針）において、リスク特定で考慮することが望ましいとされている事項はどれか。','DM-A-24-03-01','ipa_past','出典：令和6年度 春期 応用情報技術者試験 午前 問40（句読点を統一。解説は独自作成）','[{"id": 1, "body": "結果の性質及び大きさ"}, {"id": 2, "body": "残留リスクが許容可能かどうかの判断"}, {"id": 3, "body": "資産及び組織の資源の性質及び価値"}, {"id": 4, "body": "事象の起こりやすさ及び結果"}]'::jsonb,3,'リスク特定では、保護すべき資産や組織の資源の性質・価値を把握し、リスクを見いだす。結果の大きさや起こりやすさの検討はリスク分析、残留リスクの許容可否の判断は評価・受容の文脈と区別する。公式正答は資産及び組織の資源の性質及び価値である。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0035','ディープフェイクを悪用した攻撃','ディープフェイクを悪用した攻撃に該当するものはどれか。','DM-A-27-02-01','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問39（句読点を統一。解説は独自作成）','[{"id": 1, "body": "AI技術によって加工したCEOの音声を使用して従業員に電話をかけ、指定した銀行口座に送金するよう指示した。"}, {"id": 2, "body": "企業のPCをランサムウェアに感染させ、暗号化したデータを復号するための鍵と引き換えに、指定した方法で暗号資産を送付するよう指示した。"}, {"id": 3, "body": "企業の秘密情報を含むデータを不正に取得したと誤認させる電子メールを従業員に送付し、不正に取得したデータを公開しないことと引き換えに、指定した方法で暗号資産を送付するよう指示した。"}, {"id": 4, "body": "ディープウェブにて入手した認証情報でCEOの電子メールアカウントに不正にログインして偽りの電子メールを従業員に送付し、指定した銀行口座に送金するよう指示した。"}]'::jsonb,1,'ディープフェイクは、AIによって実在の人物に似た音声や映像などを生成・加工する技術である。CEOに似せた加工音声を使う手口が該当する。ランサムウェアや認証情報の不正利用とは異なる。音声や映像だけで本人と断定せず、別の経路で確認することが重要である。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0036','表の構造から取得できる情報','化粧品の製造を行っているA社では、販売代理店を通じて商品販売を行っている。今後の販売戦略に活用するために、次の三つの表を設計した。これらの表を用いるだけでは得ることのできない情報はどれか。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0037','データガバナンスを確保する理由','組織においてデータガバナンスを確保することが重要である背景及び理由として、最も適切なものはどれか。','DM-A-08-03-01','ipa_sample','出典：IPA データマネジメント試験（仮称）科目A サンプル問題 問1（2026年6月公開。読点を統一。解説は独自作成）','[{"id": 1, "body": "データの活用が広がる中で、組織内のデータの品質やセキュリティを維持し、意思決定の精度向上、法令遵守などを実現することによって、組織の価値と信頼を高めるため。"}, {"id": 2, "body": "データの活用が広がる中で、組織内のデータを部門ごとに分断（サイロ化）し、保有するデータの内容を秘匿にすることによって、部門を越えたデータアクセスを統制するため。"}, {"id": 3, "body": "デジタル技術が高度化する中で、データ基盤を導入する際の評価基準及びプロセスを組織内で確立することによって、情報システム部によるITコントロールを強化するため。"}, {"id": 4, "body": "デジタル技術が高度化する中で、データを処理する人手の業務を自動化ツールに置き換えるデジタル化を推進することによって、データ処理に関わる人的コストを最適化するため。"}]'::jsonb,1,'データガバナンスは、組織全体のデータの品質やセキュリティ、法令遵守などを支え、価値ある意思決定と組織への信頼につなげるための統制である。部門間のサイロ化を進めることではない。IT基盤の評価や業務の自動化だけに目的を限定する説明も適切ではない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0038','データ品質を低下させる対応','AIやBIツールの処理対象となるデータは、そのデータ品質を適切に維持することが重要である。データ品質の劣化につながる望ましくない対応だけを全て挙げた組合せはどれか。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0039','ビジネスメタデータの継続的な整備','メタデータを次のa〜cの三つに分類したとき、特にa（ビジネス及び業務に関するメタデータ）の整備が組織にとって課題となることが多い。この課題を解決する方法として、最も適切なものはどれか。
